use std::collections::HashMap;
use std::path::PathBuf;
use std::sync::Arc;
use parking_lot::RwLock;
use tokio::sync::broadcast;
use bytes::Bytes;
use thiserror::Error;

use crate::terminal::{PtyError, PtyManager, PtySessionState, TerminalSignal};
use crate::worktree::{WorkspaceRegistry, WorktreeIdentity, WorktreeError};

/// Service-level error handling across workspace, PTY, and remote boundaries
#[derive(Debug, Error)]
pub enum TerminalServiceError {
    #[error("Session not found: {0}")]
    SessionNotFound(String),

    #[error("Workspace error: {0}")]
    Workspace(#[from] WorktreeError),

    #[error("PTY error: {0}")]
    Pty(#[from] PtyError),

    #[error("Output subscription lagged by {0} messages")]
    SubscriptionLagged(u64),

    #[error("Internal service error: {0}")]
    Internal(String),
}

/// Metadata describing an active terminal session
#[derive(Debug, Clone)]
pub struct TerminalSessionInfo {
    pub session_id: String,
    pub workspace_id: Option<String>,
    pub worktree_path: Option<PathBuf>,
    pub worktree_label: Option<String>,
    pub title: Option<String>,
    pub state: PtySessionState,
    pub cols: u16,
    pub rows: u16,
}

/// Terminal lifecycle events broadcast to all consumers (Desktop & Remote)
#[derive(Debug, Clone)]
pub struct TerminalLifecycleEvent {
    pub session_id: String,
    pub state: TerminalLifecycleState,
    pub exit_code: Option<i32>,
    pub reason: Option<String>,
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum TerminalLifecycleState {
    Started,
    Exited,
    Failed,
}

/// Returned when a client attaches to an existing session
pub struct TerminalAttachment {
    pub session_id: String,
    /// In-memory bounded replay history at the moment of attachment
    pub history_snapshot: Bytes,
    /// Live broadcast receiver for subsequent PTY output frames
    pub live_rx: broadcast::Receiver<Bytes>,
}

/// Ring buffer for bounded recent output (512 KiB – 1 MiB)
pub struct BoundedReplayBuffer {
    capacity: usize,
    buffer: Vec<u8>,
    head: usize,
    len: usize,
}

/// Output hub per active session managing broadcast & replay history
pub struct SessionOutputHub {
    tx: broadcast::Sender<Bytes>,
    history: parking_lot::Mutex<BoundedReplayBuffer>,
}

/// Registry of output hubs for all active sessions
#[derive(Clone, Default)]
pub struct TerminalOutputHub {
    hubs: Arc<RwLock<HashMap<String, Arc<SessionOutputHub>>>>,
}

/// Core Terminal Service orchestrator
#[derive(Clone)]
pub struct TerminalService {
    pty_manager: Arc<PtyManager>,
    workspace_registry: Arc<WorkspaceRegistry>,
    output_hub: TerminalOutputHub,
    lifecycle_tx: broadcast::Sender<TerminalLifecycleEvent>,
    session_metadata: Arc<RwLock<HashMap<String, TerminalSessionInfo>>>,
}
